        if (compound.contains("HarvestedLeafState", 10)) {
            blockstate = NbtUtils.readBlockState(this.level().holderLookup(Registries.BLOCK), compound.getCompound("HarvestedLeafState"));
            if (blockstate.isAir()) {
                blockstate = null;
